{
  "sql": "SELECT name AS 厂站 FROM plant WHERE process = '氧化沟' ORDER BY id",
  "explanation": "按处理工艺筛选氧化沟的厂站并返回名称"
}

{
  "sql": "SELECT round(sum(capacity_m3d)::numeric, 0) AS 全区设计规模_m3_d FROM plant;",
  "explanation": "汇总所有厂站的设计处理规模"
}

{
  "sql": "SELECT p.name AS 厂站, d.code AS 设备编码, d.kind AS 设备类型, d.model AS 设备型号, d.rated_kw AS 额定功率_kW, d.status AS 状态 FROM device d JOIN plant p ON p.id = d.plant_id WHERE d.rated_kw = (SELECT MAX(rated_kw) FROM device) ORDER BY d.rated_kw DESC",
  "explanation": "查询设备台账中额定功率等于最大额定功率的所有设备，并关联厂站名称。"
}

{
  "sql": "SELECT round(sum(h.inflow_m3h)::numeric) AS 处理水量_m3 FROM plant_reading_1h h WHERE h.hour >= date_trunc('day', now()) - interval '1 day' AND h.hour < date_trunc('day', now())",
  "explanation": "查询昨天全区所有厂站的小时处理水量求和"
}

{
  "sql": "WITH latest AS (SELECT DISTINCT ON (r.plant_id) r.plant_id, r.tn_out, r.ts FROM plant_reading r WHERE r.ts > now() - interval '30 minutes' ORDER BY r.plant_id, r.ts DESC) SELECT p.name AS 厂站, round(l.tn_out::numeric, 2) AS 出水总氮_mgL FROM latest l JOIN plant p ON p.id = l.plant_id ORDER BY l.tn_out DESC NULLS LAST LIMIT 1;",
  "explanation": "查询最近30分钟各厂最新出水总氮，按数值降序取最高者。"
}

{
  "sql": "SELECT p.name AS 厂站, round(sum(h.inflow_m3h)::numeric) AS 处理水量_m3 FROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id WHERE h.hour >= date_trunc('week', now()) GROUP BY p.id, p.name ORDER BY p.id;",
  "explanation": "按厂站汇总本周各小时处理水量。"
}

{
  "sql": "SELECT p.name AS 厂站, round(avg(h.cod_out)::numeric, 1) AS 出水COD日均值, round(avg(h.nh3n_out)::numeric, 2) AS 出水氨氮日均值, round(avg(h.tn_out)::numeric, 2) AS 出水总氮日均值, round(avg(h.tp_out)::numeric, 3) AS 出水总磷日均值 FROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id WHERE p.name LIKE '%中心%' AND h.hour >= date_trunc('day', now()) - interval '1 day' AND h.hour < date_trunc('day', now()) GROUP BY p.id, p.name",
  "explanation": "查询昨天中心厂在小时均值表中的出水COD、氨氮、总氮、总磷四项指标的平均值"
}

{
  "sql": "SELECT round(sum(blower_kw)::numeric, 2) AS 鼓风机总耗电量_kWh, round((sum(blower_kw) / sum(inflow_m3h))::numeric, 4) AS 吨水曝气电耗_kWh FROM plant_reading_1h WHERE hour >= date_trunc('day', now()) - interval '1 day' AND hour < date_trunc('day', now())",
  "explanation": "查询昨天全区小时数据，鼓风机总耗电量为各小时平均功率累加，吨水曝气电耗为总耗电量除以总处理水量"
}

{
  "sql": "SELECT p.name AS 厂站, round(avg(r.mlss)::numeric, 2) AS 平均污泥浓度_mgL FROM plant_reading r JOIN plant p ON p.id = r.plant_id WHERE r.ts >= now() - interval '7 days' GROUP BY p.id, p.name ORDER BY p.id",
  "explanation": "从原始读数表按厂站聚合过去7天的MLSS平均值，并关联厂站名称"
}

{
  "sql": "SELECT p.name AS 厂站, round(sum(h.inflow_m3h)::numeric) AS 处理水量_m3 FROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id WHERE h.hour >= date_trunc('day', now()) - interval '1 day' AND h.hour < date_trunc('day', now()) GROUP BY p.name ORDER BY 2 DESC LIMIT 3",
  "explanation": "统计昨天各厂站小时进水量的总和并按处理水量降序取前三名"
}

{
  "sql": "SELECT p.name AS 厂站, round(avg(h.cod_out)::numeric, 1) AS 平均出水COD FROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id WHERE h.hour >= now() - interval '7 days' GROUP BY p.id, p.name ORDER BY 平均出水COD DESC LIMIT 1",
  "explanation": "查询过去7天各厂平均出水COD，按降序取第一"
}

{
  "sql": "SELECT p.name AS 厂站, count(*) AS 超标小时数, round(max(h.nh3n_out_max)::numeric, 3) AS 最高氨氮\nFROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id\nWHERE h.hour >= now() - interval '7 days' AND h.nh3n_out_max > 5\nGROUP BY p.id, p.name ORDER BY p.id",
  "explanation": "查询过去7天小时数据中出水氨氮最大值超过5mg/L的厂站，按厂站统计超标小时数和最高氨氮值"
}

{
  "sql": "SELECT p.name AS 厂站, count(*) FILTER (WHERE dr.running) AS 运行分钟数 FROM device_reading dr JOIN device d ON d.id = dr.device_id JOIN plant p ON p.id = d.plant_id WHERE d.kind = '污泥泵' AND dr.ts >= date_trunc('day', now()) - interval '1 day' AND dr.ts < date_trunc('day', now()) GROUP BY p.id, p.name ORDER BY p.id",
  "explanation": "按厂站统计昨天污泥泵设备运行记录条数，每条记录代表一分钟，从而得到运行分钟数"
}

{
  "sql": "SELECT p.name AS 厂站, round((sum(h.inflow_m3h) / p.capacity_m3d * 100)::numeric, 2) AS 负荷率_pct FROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id WHERE h.hour >= date_trunc('day', now()) - interval '1 day' AND h.hour < date_trunc('day', now()) GROUP BY p.id, p.name, p.capacity_m3d ORDER BY p.id",
  "explanation": "查询昨天各厂小时进水流量合计作为实际处理水量，除以设计规模并乘以100得到负荷率百分比"
}

