{
  "sql": "SELECT name AS 厂站名称, code AS 厂站编码, kind AS 厂站类型, process AS 处理工艺, capacity_m3d AS 设计规模_吨日 FROM plant WHERE process = '氧化沟' ORDER BY id;",
  "explanation": "查询工艺为氧化沟的厂站列表"
}

{
  "sql": "SELECT name AS 厂站名称, capacity_m3d AS 设计处理规模_吨每日 FROM plant WHERE name LIKE '%南郑中心%'",
  "explanation": "按厂站名称匹配查询设计处理规模字段 capacity_m3d"
}

{
  "sql": "SELECT kind AS 设备类型, COUNT(*) AS 设备数量, round(SUM(rated_kw)::numeric, 2) AS 总额定功率_kw FROM device GROUP BY kind ORDER BY kind;",
  "explanation": "按设备类型分组统计设备数量和额定功率总和。"
}

{
  "sql": "SELECT p.name AS 厂站名称, r.inflow_m3h AS 进水流量_m3h, r.ts AS 采集时间 FROM plant_reading r JOIN plant p ON p.id = r.plant_id WHERE p.kind = '中心厂' ORDER BY r.ts DESC LIMIT 1;",
  "explanation": "查找中心厂最新一条实时数据，获取当前进水流量"
}

{
  "sql": "WITH latest AS (SELECT DISTINCT ON (plant_id) plant_id, do_aerobic_1, do_aerobic_2 FROM plant_reading ORDER BY plant_id, ts DESC) SELECT p.name AS 厂站, round(l.do_aerobic_1::numeric, 2) AS 好氧区1溶解氧_mgL, round(l.do_aerobic_2::numeric, 2) AS 好氧区2溶解氧_mgL FROM latest l JOIN plant p ON p.id = l.plant_id ORDER BY p.id;",
  "explanation": "取每个厂站最新一条 plant_reading 记录，展示好氧区1和2的溶解氧，并关联厂站名称。"
}

{
  "sql": "SELECT p.name AS 厂站, round(r.mlss::numeric, 2) AS \"污泥浓度MLSS(mg/L)\" FROM plant_reading r JOIN plant p ON p.id = r.plant_id WHERE p.name LIKE '%协税镇%' ORDER BY r.ts DESC LIMIT 1;",
  "explanation": "从实时数据表中查询协税镇最新一条记录的MLSS值。"
}

{
  "sql": "SELECT round(COALESCE(sum(r.blower_kw),0)::numeric, 2) AS \"鼓风机耗电量_度\" FROM plant_reading_1h r JOIN plant p ON p.id = r.plant_id WHERE p.kind = '中心厂' AND r.hour >= date_trunc('day', now() - interval '1 day') AND r.hour < date_trunc('day', now())",
  "explanation": "按小时汇总中心厂昨日鼓风机功率均值（数值等于耗电量千瓦时）得到总耗电量"
}

{
  "sql": "SELECT round(SUM(inflow_m3h)::numeric, 2) AS \"处理水量（m³）\" FROM plant_reading_1h WHERE hour >= date_trunc('day', now()) - interval '1 day' AND hour < date_trunc('day', now());",
  "explanation": "查询昨日所有厂站小时处理水量总和，即全区处理水量。"
}

{
  "sql": "SELECT p.name AS 厂站名称, round(avg(h.cod_out)::numeric, 2) AS 出水COD日均值, round(avg(h.nh3n_out)::numeric, 2) AS 出水氨氮日均值, round(avg(h.tn_out)::numeric, 2) AS 出水总氮日均值, round(avg(h.tp_out)::numeric, 2) AS 出水总磷日均值 FROM plant_reading_1h h JOIN plant p ON p.id = h.plant_id WHERE p.kind = '中心厂' AND h.hour >= date_trunc('day', now()) - interval '1 day' AND h.hour < date_trunc('day', now()) GROUP BY p.name",
  "explanation": "查询中心厂昨天各出水指标的小时均值再取日均值，按厂站名称分组"
}

{
  "sql": "SELECT round(avg(pr.air_flow_m3h)::numeric, 2) AS \"平均曝气风量(m³/h)\" FROM plant_reading_1h pr JOIN plant p ON p.id = pr.plant_id WHERE p.name LIKE '%中心%' AND pr.hour >= date_trunc('day', now()) - interval '1 day' AND pr.hour < date_trunc('day', now())",
  "explanation": "从小时均值表按厂站名称匹配中心厂，计算昨日所有小时曝气风量的平均值。"
}

{
  "sql": "WITH daily AS (SELECT date_trunc('day', r.hour) AS day, SUM(r.inflow_m3h) AS total_flow, SUM(r.blower_kw) AS total_blower_kwh FROM plant_reading_1h r JOIN plant p ON p.id = r.plant_id WHERE p.name LIKE '%中心%' AND r.hour >= date_trunc('week', now()) AND r.hour < date_trunc('week', now()) + interval '1 week' GROUP BY day) SELECT to_char(day, 'YYYY-MM-DD') AS \"日期\", round(total_flow::numeric, 1) AS \"处理水量(m³)\", round(total_blower_kwh::numeric, 1) AS \"鼓风机耗电量(kWh)\", round((total_blower_kwh / NULLIF(total_flow, 0))::numeric, 4) AS \"吨水曝气电耗(kWh/m³)\" FROM daily ORDER BY day;",
  "explanation": "按周内每天汇总中心厂的处理水量与鼓风机耗电量，鼓风机耗电量除以处理水量得到吨水曝气电耗。"
}

{
  "sql": "SELECT p.name AS 厂站名称, round((sum(r.carbon_dose_kgh) / nullif(sum(r.inflow_m3h), 0))::numeric, 4) AS 吨水碳源投加量 FROM plant_reading_1h r JOIN plant p ON p.id = r.plant_id WHERE r.hour >= now() - interval '7 days' AND r.hour < now() GROUP BY p.name ORDER BY 吨水碳源投加量 DESC",
  "explanation": "按厂站汇总过去7天的碳源投加总量和处理水量，计算吨水投加量并从高到低排序"
}

{
  "sql": "SELECT DISTINCT p.name AS \"厂站名称\" FROM plant_reading_1h r JOIN plant p ON r.plant_id = p.id WHERE r.hour >= now() - interval '7 days' AND r.nh3n_out_max > 5 ORDER BY p.name;",
  "explanation": "查询过去7天内小时数据中氨氮最大值超过5mg/L的厂站并去重列出"
}

{
  "sql": "SELECT p.name AS \"厂站名称\", COALESCE(t.exceed_hours, 0) AS \"超标小时数\" FROM plant p LEFT JOIN (SELECT plant_id, count(*) FILTER (WHERE cod_out > 50 OR nh3n_out_max > 5 OR tn_out > 15 OR tp_out_max > 0.5 OR ss_out > 10) AS exceed_hours FROM plant_reading_1h WHERE hour >= date_trunc('day', now()) - interval '1 day' AND hour < date_trunc('day', now()) GROUP BY plant_id) t ON p.id = t.plant_id ORDER BY p.id",
  "explanation": "统计昨天每个厂站小时数据中任一指标超标的小时数，并通过 LEFT JOIN 列出所有厂站（含0超标）。"
}

{
  "sql": "SELECT p.name AS 厂站, r.hour AS 首次超标时间 FROM plant_reading_1h r JOIN plant p ON p.id = r.plant_id WHERE p.name LIKE '%协税%' AND r.hour >= date_trunc('week', now()) AND r.hour <= now() AND r.tp_out_max > 0.5 ORDER BY r.hour ASC LIMIT 1;",
  "explanation": "查询本周内协税镇每小时总磷最大值超过0.5 mg/L的最早整点时间"
}

{
  "sql": "SELECT p.name AS 厂站, d.code AS 设备编码, d.model AS 设备型号, d.status AS 状态 FROM device d JOIN plant p ON d.plant_id = p.id WHERE d.kind = '鼓风机' AND d.status = '备用' LIMIT 100",
  "explanation": "从设备台账关联厂站表，筛选状态为备用的鼓风机并显示所属厂站。"
}

{
  "sql": "SELECT dr.ts AS \"时间\" FROM device_reading dr JOIN device d ON dr.device_id = d.id WHERE d.code = 'P06-BL-1' AND dr.vibration_mms > 7.1 AND dr.ts >= (date_trunc('day', now()) - interval '1 day') AND dr.ts < date_trunc('day', now()) ORDER BY dr.ts ASC LIMIT 1;",
  "explanation": "通过设备编码锁定黄官镇1号鼓风机，筛选11月4日振动超过7.1mm/s的记录并按时间升序取第一条，即首次超标时间。"
}

{
  "sql": "WITH yesterday AS (SELECT COALESCE(SUM(inflow_m3h),0) AS total FROM plant_reading_1h WHERE hour >= date_trunc('day', now()) - interval '1 day' AND hour < date_trunc('day', now())), day_before AS (SELECT COALESCE(SUM(inflow_m3h),0) AS total FROM plant_reading_1h WHERE hour >= date_trunc('day', now()) - interval '2 days' AND hour < date_trunc('day', now()) - interval '1 day') SELECT ROUND((y.total - db.total)::numeric, 2) AS \"处理水量差值_立方米\" FROM yesterday y, day_before db;",
  "explanation": "分别汇总昨天和前天的小时处理水量，然后相减得到差值。"
}

{
  "sql": "SELECT round(min(LEAST(pr.do_aerobic_1, pr.do_aerobic_2))::numeric, 2) AS \"最低溶解氧(mg/L)\" FROM plant_reading pr JOIN plant p ON pr.plant_id = p.id WHERE p.name LIKE '%黄官%' AND pr.ts >= (date_trunc('day', now()) - interval '1 day') + interval '15 hours' AND pr.ts < (date_trunc('day', now()) - interval '1 day') + interval '18 hours'",
  "explanation": "查询黄官镇污水处理站11月4日15:00至18:00原始数据中两个好氧区溶解氧的最小值。"
}

{
  "sql": "WITH station_avg AS (SELECT p.name, AVG(r.cod_in) AS avg_cod FROM plant_reading_1h r JOIN plant p ON p.id = r.plant_id WHERE r.hour >= now() - interval '7 days' GROUP BY p.name), overall_avg AS (SELECT AVG(cod_in) AS avg_cod FROM plant_reading_1h WHERE hour >= now() - interval '7 days') SELECT s.name AS \"厂站名称\", round(s.avg_cod::numeric, 2) AS \"平均进水COD(mg/L)\" FROM station_avg s, overall_avg o WHERE s.avg_cod > o.avg_cod ORDER BY s.avg_cod DESC;",
  "explanation": "按过去7天各厂站小时平均进水COD求平均，与全区所有小时记录的平均COD比较，筛选出高于全区平均的厂站。"
}

